SELECT datasetkey, level2gid, "month", v_scientificname, occurrence.gbif_classification.specieskey AS specieskey, COUNT(*) AS n FROM occurrence WHERE occurrence.gbif_classification.classkey = '212' AND level0gid IN ('USA', 'CAN') AND datasetkey IN ('4fa7b334-ce0d-4e88-aaae-2e0c138d049e', '50c9509d-22c7-4a22-a47d-8c48425ef4a7') AND occurrencestatus = 'PRESENT' GROUP BY datasetkey, level2gid, "month", v_scientificname, occurrence.gbif_classification.specieskey
